const missionCache=[],seenChallenges=new Set();
function make(id){
 if(!Number.isInteger(id)||id<0||id>=1000)throw Error('Nomor misi tidak valid');
 for(let index=missionCache.length;index<=id;index++){
  let candidate,key,variant=0;
  do{if(variant>=1000)throw Error('Tidak bisa membuat tantangan unik');candidate=rawMake(index,variant++);key=challengeKey(candidate);}while(seenChallenges.has(key));
  seenChallenges.add(key);missionCache.push(candidate);
 }
 return JSON.parse(JSON.stringify(missionCache[id]));
}
function matches(c,r){return r.op==='eq'?c[r.field]===r.value:r.op==='ne'?c[r.field]!==r.value:r.value.includes(c[r.field]);}
